select * from CustomerDataset 
--Q1. What is the total revenue generated by male vs. female customers?

select gender, sum(purchase_amount) as revenue
from CustomerDataset 
group by gender 
order by revenue asc


--Q2. Which customers used a discount but still spent more than the average purchase amount?

select customer_id ,purchase_amount,
COUNT(*) OVER() AS total_matching_customers
from CustomerDataset
where discount_applied = 'yes' and purchase_amount > (select avg(purchase_amount) from CustomerDataset)


--Q3. Which are the top 5 products with the highest average review rating?(including ties)

SELECT top 5 with ties
    item_purchased, 
    ROUND(AVG(CAST(review_rating AS FLOAT)), 2) AS "Average Product rating"
FROM CustomerDataset
GROUP BY item_purchased
ORDER BY AVG(CAST(review_rating AS FLOAT)) DESC 


--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.

select  shipping_type , 
round(avg(purchase_amount),2) as avg_purchase_amount
from CustomerDataset
where shipping_type in ('standard','express')
group by shipping_type


--Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

select subscription_status,
count(customer_id) as total_customer,
round(avg(purchase_amount),2) as avg_spend,
round(sum(purchase_amount),2) as total_revenue
from CustomerDataset
group by subscription_status
order by total_revenue desc, avg_spend desc

--Q6. Which 5 products have the highest percentage of purchases with discounts
--applied?

SELECT TOP 5
    item_purchased,
    CAST(ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 2) AS DECIMAL(5,2)) AS discount_rate
FROM CustomerDataset
GROUP BY item_purchased
ORDER BY discount_rate DESC;


--Q7. Segment customers into New, Returning, and Loyal based on their total 
--number of previous purchases, and show the count of each segment.
-- solved with CTE
with customer_type as (
select customer_id, previous_purchases,
case
when previous_purchases <= 1 then 'new'
when previous_purchases between 2 and 10 then 'returning'
else 'loyal'
end as customer_segment
from CustomerDataset
)

select customer_segment, count(*) as 'number of customers'
from customer_type
group by customer_segment




--Q8. What are the top 3 most purchased products within each category?
-- solve with CTE
;with item_counts as(
select category,
item_purchased,
count(customer_id) as total_orders,
dense_rank() over(partition by category order by count(customer_id) desc) as item_rank
from CustomerDataset
group by category , item_purchased
)

select item_rank , category ,item_purchased , total_orders
from item_counts
where item_rank <=3;



--Q9. Are customers who are repeat buyers (more than 5 previous purchases) 
--also likely to subscribe?

SELECT 
    subscription_status,
    COUNT(customer_id) AS repeat_buyers,
    CAST(ROUND(100.0 * COUNT(customer_id) / SUM(COUNT(customer_id)) OVER(), 2) AS DECIMAL(5,2)) AS subscription_pct
FROM CustomerDataset
WHERE previous_purchases > 5
GROUP BY subscription_status;




--Q10. What is the revenue contribution of each age group?

SELECT 
    age_group,
    ROUND(SUM(purchase_amount), 2) AS total_revenue,
    CAST(ROUND(100.0 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER(), 2) AS DECIMAL(5,2)) AS revenue_pct
FROM CustomerDataset
GROUP BY age_group 
ORDER BY total_revenue DESC;


--Q11. How do purchasing patterns compare across sales channels (Online Home Delivery vs. Offline Store Pickup)?

SELECT 
    CASE 
        WHEN shipping_type = 'Store Pickup' THEN 'Offline (Store Pickup)'
        ELSE 'Online (Home Delivery)'
    END AS sales_channel,
    COUNT(customer_id) AS total_orders,
    CAST(ROUND(100.0 * COUNT(customer_id) / SUM(COUNT(customer_id)) OVER(), 2) AS DECIMAL(5,2)) AS order_share_pct,
    ROUND(SUM(purchase_amount), 2) AS total_revenue,
    CAST(ROUND(100.0 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER(), 2) AS DECIMAL(5,2)) AS revenue_share_pct,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM CustomerDataset
GROUP BY 
    CASE 
        WHEN shipping_type = 'Store Pickup' THEN 'Offline (Store Pickup)'
        ELSE 'Online (Home Delivery)'
    END
ORDER BY total_revenue DESC;


--Q12. How do customer orders, total revenue, and average spend vary across seasons?

SELECT 
    season,
    COUNT(customer_id) AS total_orders,
    ROUND(SUM(purchase_amount), 2) AS total_revenue,
    CAST(ROUND(100.0 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER(), 2) AS DECIMAL(5,2)) AS revenue_share_pct,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM CustomerDataset
GROUP BY season
ORDER BY total_revenue DESC;


--Q13. Which payment methods drive the highest revenue, order volume, and average spend?

SELECT 
    payment_method,
    COUNT(customer_id) AS total_orders,
    ROUND(SUM(purchase_amount), 2) AS total_revenue,
    CAST(ROUND(100.0 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER(), 2) AS DECIMAL(5,2)) AS revenue_share_pct,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM CustomerDataset
GROUP BY payment_method
ORDER BY total_revenue DESC;